/*
  FrankAI knot streaming indicator — "Draw, fade, repeat"
  ----------------------------------------------------------------
  Traced directly from FranAI-logo.png (outer knot silhouette + 4 inner
  loop holes), smoothed into cubic-bezier SVG paths so it draws with
  real curves instead of faceted polygon segments.

  Usage:
    import { KnotStreamer } from './knot-streamer.js';

    const streamer = new KnotStreamer(document.getElementById('ai-avatar-slot'));
    streamer.mount();

    // when FrankAI starts responding:
    streamer.start();

    // when the response finishes:
    streamer.stop();

  Requires knot-streamer.css to be loaded on the page.
  No external dependencies. Pure DOM + CSS animation, JS only toggles
  the .is-streaming class and builds the SVG once.
*/

