// ============================================================
//   STATIC LOGO MARK — same traced knot geometry AND the same
//   stroke-based rendering style as the animated KnotStreamer (fine
//   outlined line-art, not solid fill), just permanently "drawn"
//   instead of cycling through the draw/fade animation. Uses its own
//   CSS class (.knot-logo-static, see knot-streamer.css) rather than
//   reusing KnotStreamer's .knot-streamer/.is-streaming classes,
//   since knot-streamer.css deliberately hides non-streaming paths
//   (opacity: 0) — that's correct for a cursor that should stay
//   invisible until streaming starts, but wrong for an avatar mark
//   that should always be visible.
// ============================================================
export function buildKnotLogoSVG({
  colorOuter = '#FFB800',
  colorInner = '#FF8C00',
  strokeOuter = 1,
  strokeInner = 1,
} = {}) {
  return `
    <div class="knot-logo-static"
         style="--knot-color-outer:${colorOuter}; --knot-color-inner:${colorInner}; --knot-stroke-outer:${strokeOuter}; --knot-stroke-inner:${strokeInner};">
      <svg viewBox="0 0 1024 1024" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
        <circle class="knot-logo-static-ring" cx="512" cy="512" r="480"></circle>
        <path class="knot-logo-static-outer" d="${KNOT_PATHS.outer}"></path>
        <path class="knot-logo-static-inner" d="${KNOT_PATHS.inner0}"></path>
        <path class="knot-logo-static-inner" d="${KNOT_PATHS.inner1}"></path>
        <path class="knot-logo-static-inner" d="${KNOT_PATHS.inner2}"></path>
        <path class="knot-logo-static-inner" d="${KNOT_PATHS.inner3}"></path>
      </svg>
    </div>`;
}

export class KnotStreamer {
  /**
   * @param {HTMLElement} container - element to mount the SVG into
   * @param {Object} [options]
   * @param {string} [options.size='64px'] - CSS size, e.g. '48px', '4rem'
   * @param {string} [options.colorOuter='#FFB800']
   * @param {string} [options.colorInner='#FF8C00']
   * @param {number} [options.strokeOuter=10]
   * @param {number} [options.strokeInner=7]
   * @param {number} [options.cycleDuration=3.2] - seconds per draw/fade loop
   * @param {boolean} [options.autoStart=false]
   */
  constructor(container, options = {}) {
    if (!container) {
      throw new Error('KnotStreamer: container element is required');
    }
    this.container = container;
    this.options = {
      size: '64px',
      colorOuter: '#FFB800',
      colorInner: '#FF8C00',
      strokeOuter: 1,
      strokeInner: 1,
      cycleDuration: 3.2,
      autoStart: false,
      ...options,
    };
    this.el = null;
    this._mounted = false;
  }

  mount() {
    if (this._mounted) return this;

    const wrap = document.createElement('div');
    wrap.className = 'knot-streamer';
    wrap.style.setProperty('--knot-size', this.options.size);
    wrap.style.setProperty('--knot-color-outer', this.options.colorOuter);
    wrap.style.setProperty('--knot-color-inner', this.options.colorInner);
    wrap.style.setProperty('--knot-stroke-outer', this.options.strokeOuter);
    wrap.style.setProperty('--knot-stroke-inner', this.options.strokeInner);
    wrap.style.setProperty('--knot-cycle-duration', `${this.options.cycleDuration}s`);

    wrap.innerHTML = `
      <svg viewBox="0 0 1024 1024" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
        <circle class="knot-ring" cx="512" cy="512" r="480"></circle>
        <path class="knot-outer" d="${KNOT_PATHS.outer}"></path>
        <path class="knot-inner knot-inner-0" d="${KNOT_PATHS.inner0}"></path>
        <path class="knot-inner knot-inner-1" d="${KNOT_PATHS.inner1}"></path>
        <path class="knot-inner knot-inner-2" d="${KNOT_PATHS.inner2}"></path>
        <path class="knot-inner knot-inner-3" d="${KNOT_PATHS.inner3}"></path>
      </svg>
    `;

    this.container.appendChild(wrap);
    this.el = wrap;
    this._mounted = true;

    if (this.options.autoStart) this.start();
    return this;
  }

  start() {
    if (!this._mounted) this.mount();
    this.el.classList.add('is-streaming');
    return this;
  }

  stop() {
    if (this.el) this.el.classList.remove('is-streaming');
    return this;
  }

  toggle(force) {
    if (typeof force === 'boolean') {
      force ? this.start() : this.stop();
    } else {
      this.el.classList.contains('is-streaming') ? this.stop() : this.start();
    }
    return this;
  }

  setCycleDuration(seconds) {
    this.options.cycleDuration = seconds;
    if (this.el) this.el.style.setProperty('--knot-cycle-duration', `${seconds}s`);
    return this;
  }

  destroy() {
    if (this.el && this.el.parentNode) {
      this.el.parentNode.removeChild(this.el);
    }
    this.el = null;
    this._mounted = false;
  }
}

export { KNOT_PATHS, ARC_LENGTHS };